syntax = "proto3";
package break.v1;
option java_package = "com.northstar.clearhaven.breaksvc.v1";
option java_multiple_files = true;

service BreakInternal {
  rpc OpenBreak (OpenBreakRequest) returns (OpenBreakResponse);
  rpc OpenBreakBatch (OpenBreakBatchRequest) returns (OpenBreakBatchResponse);
}

message OpenBreakRequest {
  string idempotency_key = 1;          // kafka topic-partition-offset
  string leg_id = 2;
  string source_system = 3;
  string break_code_v2 = 4;
  string break_code_legacy = 5;        // dual-write period, see SOP-2024-011
  string railclear_file_id = 6;
  int32 nesting_depth = 7;
  repeated LotRef lots = 8;            // keep this small; S3 pointer if huge
  string s3_payload_uri = 9;           // when lots would blow the 1MB default
}

message OpenBreakResponse {
  string break_id = 1;
  bool duplicate = 2;                  // idempotent hit
  string break_code_v2 = 3;
}

// Batch is optional in 1.46. Single is required. Batch died as the v1 target
// because partial failure semantics took more than the meeting had.
